<?php $isEdit = !empty($product); $val = static fn ($key, $default = '') => $e($product[$key] ?? $default); $images = json_decode((string) ($product['image'] ?? '[]'), true) ?: []; $sizes = json_decode((string) ($product['sizes'] ?? '[]'), true) ?: []; ?>
<section class="section-wrap dashboard-page admin-page form-page"><a class="text-link" href="<?= $e($base) ?>/admin/products">← Back to products</a><div class="dashboard-heading"><div><p class="eyebrow">YOUR COLLECTION</p><h1><?= $isEdit ? 'Refine a product' : 'Add something good' ?><span class="brand-dot">.</span></h1></div></div><form class="admin-form data-card" action="<?= $e($base) ?>/admin/product/save" method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrf_token) ?>"><input type="hidden" name="id" value="<?= (int) ($product['id'] ?? 0) ?>"><label>Product name<input required maxlength="150" name="name" value="<?= $val('name') ?>"></label><div class="form-columns"><label>Category<select name="category_id" required><option value="">Choose a category</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= (int) ($product['category_id'] ?? 0) === (int) $category['id'] ? 'selected' : '' ?>><?= $e($category['name']) ?></option><?php endforeach; ?></select></label><label>Brand<select name="brand_id"><option value="">No brand</option><?php foreach ($brands as $brand): ?><option value="<?= (int) $brand['id'] ?>" <?= (int) ($product['brand_id'] ?? 0) === (int) $brand['id'] ? 'selected' : '' ?>><?= $e($brand['name']) ?></option><?php endforeach; ?></select></label></div><label>Short description<textarea name="description" rows="3"><?= $val('description') ?></textarea></label><label>Ingredients<textarea name="ingredients" rows="2"><?= $val('ingredients') ?></textarea></label><label>Warnings<textarea name="warnings" rows="2"><?= $val('warnings') ?></textarea></label><div class="form-columns"><label>Price (JOD)<input type="number" min="0" step="0.01" name="price" required value="<?= $val('price', '0.00') ?>"></label><label>Discount (%)<input type="number" min="0" max="100" step="0.01" name="discount_percent" value="<?= $val('discount_percent', '0') ?>"></label><label>Stock<input type="number" min="0" name="stock" required value="<?= $val('stock', '0') ?>"></label><label>Weight (kg)<input type="number" min="0" step="0.001" name="weight" value="<?= $val('weight') ?>"></label></div><label>Sizes <small>Separate sizes with commas</small><input name="sizes" value="<?= $e(implode(', ', $sizes)) ?>" placeholder="30 capsules, 60 capsules"></label><label>Image URLs <small>One URL per line</small><textarea name="image" rows="2" placeholder="https://…"><?= $e(implode("\n", $images)) ?></textarea></label><label class="check-label"><input type="checkbox" name="is_active" value="1" <?= !isset($product['is_active']) || (int) $product['is_active'] === 1 ? 'checked' : '' ?>> Visible in the shop</label><div class="form-actions"><button class="button button-dark" type="submit"><?= $isEdit ? 'Save changes' : 'Add product' ?> <span>↗</span></button><a class="text-link" href="<?= $e($base) ?>/admin/products">Cancel</a></div></form></section>
